CREATE TABLE IF NOT EXISTS inv_warehouses (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id INT UNSIGNED NOT NULL, code VARCHAR(40) NOT NULL, name VARCHAR(150) NOT NULL, location VARCHAR(255) NULL, note VARCHAR(255) NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uq_inv_wh_branch_code(branch_id,code), KEY ix_inv_wh_branch_active(branch_id,active), CONSTRAINT fk_inv_wh_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE RESTRICT); ALTER TABLE inv_stock_ledger ADD COLUMN warehouse_id INT UNSIGNED NULL AFTER branch_id, ADD KEY ix_inv_stock_warehouse(item_id,branch_id,warehouse_id,transaction_date), ADD CONSTRAINT fk_inv_stock_warehouse FOREIGN KEY(warehouse_id) REFERENCES inv_warehouses(id) ON DELETE RESTRICT; ALTER TABLE inv_receipts ADD COLUMN warehouse_id INT UNSIGNED NULL AFTER branch_id, ADD CONSTRAINT fk_inv_receipt_warehouse FOREIGN KEY(warehouse_id) REFERENCES inv_warehouses(id) ON DELETE RESTRICT; ALTER TABLE inv_issues ADD COLUMN warehouse_id INT UNSIGNED NULL AFTER branch_id, ADD CONSTRAINT fk_inv_issue_warehouse FOREIGN KEY(warehouse_id) REFERENCES inv_warehouses(id) ON DELETE RESTRICT;